INSERT INTO CORE.CLINICAL_DOCUMENT (doc_id, patient_id, note_type, encounter_date, author_npi, title, text, attach_on_request) SELECT $$doc-001-1$$, $$pt-001$$, $$Office visit$$, $$2026-08-28$$, $$1234567893$$, $$Sleep evaluation$$, $$Face-to-face evaluation for suspected obstructive sleep apnea. Patient reports loud snoring, witnessed apneas and excessive daytime sleepiness. Epworth Sleepiness Scale score 14. BMI 34. Plan: attended in-lab polysomnography.$$, FALSE;
INSERT INTO CORE.CLINICAL_DOCUMENT (doc_id, patient_id, note_type, encounter_date, author_npi, title, text, attach_on_request) SELECT $$doc-001-2$$, $$pt-001$$, $$Sleep study$$, $$2026-09-15$$, $$1477589632$$, $$Polysomnography report$$, $$Attended in-lab polysomnography performed on 2026-09-15. Total sleep time 6.1 hours. Apnea-hypopnea index (AHI) of 22 events per hour. Lowest oxygen saturation 84%. Impression: moderate obstructive sleep apnea. Recommend CPAP therapy.$$, FALSE;
INSERT INTO CORE.CLINICAL_DOCUMENT (doc_id, patient_id, note_type, encounter_date, author_npi, title, text, attach_on_request) SELECT $$doc-002-1$$, $$pt-002$$, $$Office visit$$, $$2026-08-25$$, $$1234567893$$, $$Back pain visit$$, $$Low back pain radiating to the left leg for 2 weeks after lifting a heavy box. Started naproxen 500 mg twice daily and referred to physical therapy. No bowel or bladder changes. No saddle anesthesia. Strength 5/5 bilaterally, positive straight-leg raise on the left.$$, FALSE;
INSERT INTO CORE.CLINICAL_DOCUMENT (doc_id, patient_id, note_type, encounter_date, author_npi, title, text, attach_on_request) SELECT $$doc-002-2$$, $$pt-002$$, $$Office visit$$, $$2026-09-15$$, $$1234567893$$, $$Back pain follow-up$$, $$Follow-up for lumbar radiculopathy. Radicular pain persists after 3 weeks of naproxen and home exercises. Physical therapy started on 2026-09-02. Neurological exam unchanged. Discussed MRI lumbar spine.$$, FALSE;
INSERT INTO CORE.CLINICAL_DOCUMENT (doc_id, patient_id, note_type, encounter_date, author_npi, title, text, attach_on_request) SELECT $$doc-002-3$$, $$pt-002$$, $$Physical therapy$$, $$2026-10-14$$, $$1093817460$$, $$Physical therapy re-evaluation$$, $$Physical therapy re-evaluation. Patient completed 6 weeks of supervised physical therapy between 2026-09-02 and 2026-10-14, in addition to NSAIDs. Radicular symptoms persist with limited progress. Recommend imaging and specialist review.$$, TRUE;
INSERT INTO CORE.CLINICAL_DOCUMENT (doc_id, patient_id, note_type, encounter_date, author_npi, title, text, attach_on_request) SELECT $$doc-003-1$$, $$pt-003$$, $$Urgent care$$, $$2026-10-16$$, $$1477589632$$, $$Urgent evaluation$$, $$Acute low back pain for 5 days. New saddle anesthesia and urinary retention requiring catheterization. Decreased rectal tone on exam. Concern for cauda equina syndrome. Urgent MRI lumbar spine requested.$$, FALSE;
INSERT INTO CORE.CLINICAL_DOCUMENT (doc_id, patient_id, note_type, encounter_date, author_npi, title, text, attach_on_request) SELECT $$doc-004-1$$, $$pt-004$$, $$Pulmonology visit$$, $$2026-10-02$$, $$1234567893$$, $$COPD follow-up$$, $$COPD, GOLD 3, with progressive dyspnea on exertion. Resting room-air SpO2 92%. Six-minute walk test on room air: lowest SpO2 90%. Overnight oximetry: nadir SpO2 91%, no time below 88%. Patient requests home oxygen for breathlessness.$$, FALSE;
INSERT INTO CORE.CLINICAL_DOCUMENT (doc_id, patient_id, note_type, encounter_date, author_npi, title, text, attach_on_request) SELECT $$doc-005-1$$, $$pt-005$$, $$Office visit$$, $$2026-10-10$$, $$1234567893$$, $$Weight management follow-up$$, $$Weight management follow-up. Patient has completed 12 weeks at the semaglutide 2.4 mg weekly maintenance dose. Weight 108.5 kg from a baseline of 112.0 kg (3.1% loss). Tolerating medication with mild nausea. Requests continuation.$$, FALSE;
