INSERT INTO AI.POLICY_DOC_CHUNKS (chunk_id, policy_doc_id, payer_id, service_code, section_id, section_title, effective_date, chunk_text) SELECT $$POL-DEMO-LSMRI-v1#01$$, $$POL-DEMO-LSMRI-v1$$, $$payer-demo$$, $$72148$$, $$MRI-1$$, $$MRI-1 Scope$$, $$2026-01-01$$, $$Applies to CPT 72148 for low back pain with or without radiculopathy in adults.$$;
INSERT INTO AI.POLICY_DOC_CHUNKS (chunk_id, policy_doc_id, payer_id, service_code, section_id, section_title, effective_date, chunk_text) SELECT $$POL-DEMO-LSMRI-v1#02$$, $$POL-DEMO-LSMRI-v1$$, $$payer-demo$$, $$72148$$, $$MRI-2$$, $$MRI-2 Gold card$$, $$2026-01-01$$, $$Ordering practitioners with a gold-card status for this service do not need prior authorization.$$;
INSERT INTO AI.POLICY_DOC_CHUNKS (chunk_id, policy_doc_id, payer_id, service_code, section_id, section_title, effective_date, chunk_text) SELECT $$POL-DEMO-LSMRI-v1#03$$, $$POL-DEMO-LSMRI-v1$$, $$payer-demo$$, $$72148$$, $$MRI-3$$, $$MRI-3 Medical necessity$$, $$2026-01-01$$, $$Either section 3.1 or section 3.2 must be met.$$;
INSERT INTO AI.POLICY_DOC_CHUNKS (chunk_id, policy_doc_id, payer_id, service_code, section_id, section_title, effective_date, chunk_text) SELECT $$POL-DEMO-LSMRI-v1#04$$, $$POL-DEMO-LSMRI-v1$$, $$payer-demo$$, $$72148$$, $$MRI-3.1$$, $$MRI-3.1 Red-flag findings$$, $$2026-01-01$$, $$Imaging is appropriate without a trial of conservative care when the record documents cauda equina signs (saddle anesthesia, new bladder or bowel dysfunction), progressive or severe neurological deficit, suspected cancer, suspected infection, or significant trauma.$$;
INSERT INTO AI.POLICY_DOC_CHUNKS (chunk_id, policy_doc_id, payer_id, service_code, section_id, section_title, effective_date, chunk_text) SELECT $$POL-DEMO-LSMRI-v1#05$$, $$POL-DEMO-LSMRI-v1$$, $$payer-demo$$, $$72148$$, $$MRI-3.2$$, $$MRI-3.2 Failed conservative care$$, $$2026-01-01$$, $$Symptoms persist after at least 6 weeks of conservative care, such as anti-inflammatory medication, physical therapy, a home exercise program or activity modification.$$;
INSERT INTO AI.POLICY_DOC_CHUNKS (chunk_id, policy_doc_id, payer_id, service_code, section_id, section_title, effective_date, chunk_text) SELECT $$POL-DEMO-LSMRI-v1#06$$, $$POL-DEMO-LSMRI-v1$$, $$payer-demo$$, $$72148$$, $$MRI-4$$, $$MRI-4 Documentation$$, $$2026-01-01$$, $$When conservative care is under 6 weeks and no red flag is documented, the request is pended with a request for physical therapy notes or other records of conservative care.$$;
INSERT INTO AI.POLICY_DOC_CHUNKS (chunk_id, policy_doc_id, payer_id, service_code, section_id, section_title, effective_date, chunk_text) SELECT $$POL-DEMO-O2-v1#00$$, $$POL-DEMO-O2-v1$$, $$payer-demo$$, $$E1390$$, $$POL-DEMO-O2-v1$$, $$POL-DEMO-O2-v1 — Home oxygen therapy$$, $$2026-01-01$$, $$Demo Health Plan, synthetic policy for the AuthBridge hackathon demo. Self-authored; it paraphrases the public Medicare national coverage determination for home oxygen (NCD 240.2) and is not a real payer policy.$$;
INSERT INTO AI.POLICY_DOC_CHUNKS (chunk_id, policy_doc_id, payer_id, service_code, section_id, section_title, effective_date, chunk_text) SELECT $$POL-DEMO-O2-v1#01$$, $$POL-DEMO-O2-v1$$, $$payer-demo$$, $$E1390$$, $$O2-1$$, $$O2-1 Scope$$, $$2026-01-01$$, $$Applies to stationary oxygen concentrators (HCPCS E1390) for adults with chronic lung disease.$$;
INSERT INTO AI.POLICY_DOC_CHUNKS (chunk_id, policy_doc_id, payer_id, service_code, section_id, section_title, effective_date, chunk_text) SELECT $$POL-DEMO-O2-v1#02$$, $$POL-DEMO-O2-v1$$, $$payer-demo$$, $$E1390$$, $$O2-2$$, $$O2-2 Qualifying oxygen saturation$$, $$2026-01-01$$, $$Coverage requires at least one qualifying measurement on room air, taken during a stable period.$$;
INSERT INTO AI.POLICY_DOC_CHUNKS (chunk_id, policy_doc_id, payer_id, service_code, section_id, section_title, effective_date, chunk_text) SELECT $$POL-DEMO-O2-v1#03$$, $$POL-DEMO-O2-v1$$, $$payer-demo$$, $$E1390$$, $$O2-2.1$$, $$O2-2.1 At rest$$, $$2026-01-01$$, $$Arterial oxygen saturation of 88% or less while awake and at rest.$$;
INSERT INTO AI.POLICY_DOC_CHUNKS (chunk_id, policy_doc_id, payer_id, service_code, section_id, section_title, effective_date, chunk_text) SELECT $$POL-DEMO-O2-v1#04$$, $$POL-DEMO-O2-v1$$, $$payer-demo$$, $$E1390$$, $$O2-2.2$$, $$O2-2.2 During exercise$$, $$2026-01-01$$, $$Arterial oxygen saturation of 88% or less during exercise, with documented improvement on oxygen.$$;
INSERT INTO AI.POLICY_DOC_CHUNKS (chunk_id, policy_doc_id, payer_id, service_code, section_id, section_title, effective_date, chunk_text) SELECT $$POL-DEMO-O2-v1#05$$, $$POL-DEMO-O2-v1$$, $$payer-demo$$, $$E1390$$, $$O2-2.3$$, $$O2-2.3 During sleep$$, $$2026-01-01$$, $$Arterial oxygen saturation of 88% or less for at least 5 minutes during sleep.$$;
INSERT INTO AI.POLICY_DOC_CHUNKS (chunk_id, policy_doc_id, payer_id, service_code, section_id, section_title, effective_date, chunk_text) SELECT $$POL-DEMO-O2-v1#06$$, $$POL-DEMO-O2-v1$$, $$payer-demo$$, $$E1390$$, $$O2-3$$, $$O2-3 Measurement caution$$, $$2026-01-01$$, $$Pulse oximetry can overestimate oxygen saturation in people with darker skin pigmentation. Reviewers should consider arterial blood gas results when oximetry is borderline.$$;
INSERT INTO AI.POLICY_DOC_CHUNKS (chunk_id, policy_doc_id, payer_id, service_code, section_id, section_title, effective_date, chunk_text) SELECT $$POL-DEMO-O2-v1#07$$, $$POL-DEMO-O2-v1$$, $$payer-demo$$, $$E1390$$, $$O2-4$$, $$O2-4 Decisions$$, $$2026-01-01$$, $$Breathlessness alone does not qualify. Requests that do not meet section 2 go to a clinician for review; the system never denies them automatically.$$;
