INSERT INTO AI.POLICY_DOC_CHUNKS (chunk_id, policy_doc_id, payer_id, service_code, section_id, section_title, effective_date, chunk_text) SELECT $$POL-DEMO-PAP-v1#01$$, $$POL-DEMO-PAP-v1$$, $$payer-demo$$, $$E0601$$, $$PAP-1$$, $$PAP-1 Scope$$, $$2026-01-01$$, $$Applies to initial coverage of a CPAP device (HCPCS E0601) for adults with obstructive sleep apnea.$$;
